/**
 * @name ui/logos
 * @description Official protocol logo data URIs for MCP Apps UI cards.
 *
 * All logos are real brand assets fetched from official sources:
 * - SOL, USDC, USDT, Orca, Raydium: cryptologos.cc (official SVG)
 * - Jupiter: jup.ag/favicon.svg (official SVG)
 * - Meteora: meteora.ag/icons/v2.svg (official SVG)
 * - Adrena: adrena.xyz (official SVG)
 * - MagicBlock: magicblock.xyz apple-touch-icon (official PNG 256x256)
 * - Metaplex: metaplex.com/favicon.png (official PNG 256x256)
 *
 * Base64 data URIs prevent gradient ID collisions when the same
 * logo appears multiple times in a single HTML document.
 *
 * @module ui/logos
 */


export const SOL_LOGO_URI = `data:image/svg+xml;base64,`;

export const USDC_LOGO_URI = `data:image/svg+xml;base64,`;

